import{_ as e,a as t,b as d,c as o,d as r,e as l}from"./chunks/ee-ohos-12.DprJisAV.js";import{_ as n,o as s,c as v,a3 as f}from"./chunks/framework.BveOjhN0.js";const E=JSON.parse('{"title":"鸿蒙应用","description":"","frontmatter":{"title":"鸿蒙应用"},"headers":[],"relativePath":"zh/050.openharmony/02.hap.md","filePath":"zh/050.openharmony/02.hap.md","lastUpdated":1782647142000}'),i={name:"zh/050.openharmony/02.hap.md"};function c(p,a,g,h,m,b){return s(),v("div",null,[...a[0]||(a[0]=[f('<div class="hero" data-v-da27ea3f><div class="hero-badges" data-v-da27ea3f><span class="badge badge--star" data-v-da27ea3f>⭐ 8000+ Star</span><span class="badge badge--version" data-v-da27ea3f>🚀 v5</span><span class="badge badge--ohos" data-v-da27ea3f>🪶 鸿蒙 HarmonyOS</span></div><h1 class="hero-title" data-v-da27ea3f>ElectronEgg: 全新升级v5 - 轻松开发鸿蒙应用</h1><div class="hero-actions" data-v-da27ea3f><a class="btn btn--primary" href="https://github.com/dromara/electron-egg" target="_blank" rel="noopener" data-v-da27ea3f>GitHub 仓库 →</a><a class="btn btn--ghost" href="#写在最后" data-v-da27ea3f>加入社区</a></div></div><blockquote data-v-da27ea3f><p data-v-da27ea3f>一套代码，打包 Windows、Mac、Linux，现在还能直接跑在鸿蒙（HarmonyOS）上。ElectronEgg v5 带着鸿蒙支持来了。</p></blockquote><h2 id="写在前面" tabindex="-1" data-v-da27ea3f>写在前面 <a class="header-anchor" href="#写在前面" aria-label="Permalink to &quot;写在前面&quot;" data-v-da27ea3f>​</a></h2><p data-v-da27ea3f><a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-da27ea3f>ElectronEgg</a> 自开源以来，一直的愿景很简单：<strong data-v-da27ea3f>让所有开发者都能学会桌面软件研发</strong>。它把前端、服务端的工程化思维带进桌面开发，用一套清晰的 controller / service / preload 分层架构，把 Electron 的复杂度封装起来。目前框架在全网已累计 <strong data-v-da27ea3f>8000+ Star</strong>，经过大量团队长期实践验证，请放心使用。</p><p data-v-da27ea3f>v5 版本在此基础上完成了一次全新升级，最重磅的能力之一，就是——<strong data-v-da27ea3f>轻松开发鸿蒙应用</strong>。</p><p data-v-da27ea3f>经过不断尝试，终于把 ElectronEgg 运行在鸿蒙设备上，虽然现在是<strong data-v-da27ea3f>测试阶段</strong>，但已经跑通了整个流程，效果图见下方。</p><h2 id="鸿蒙支持-一套代码-跑在-harmonyos-上" tabindex="-1" data-v-da27ea3f>鸿蒙支持：一套代码，跑在 HarmonyOS 上 <a class="header-anchor" href="#鸿蒙支持-一套代码-跑在-harmonyos-上" aria-label="Permalink to &quot;鸿蒙支持：一套代码，跑在 HarmonyOS 上&quot;" data-v-da27ea3f>​</a></h2><p data-v-da27ea3f>过去，把 Electron 应用搬到鸿蒙上几乎是一件&quot;重新写一遍&quot;的事。v5 把构建产物自动提取并拷贝到 HarmonyOS HAP 的资源目录中，由 HAP 工程的 web 引擎加载。<strong data-v-da27ea3f>你现有的 ElectronEgg 业务代码，几乎不用改，就能以鸿蒙应用的形式运行。</strong></p><p data-v-da27ea3f>下面是 ElectronEgg 的 demo 应用在 HarmonyOS 上的真实运行效果：</p><blockquote data-v-da27ea3f><p data-v-da27ea3f>应用已安装到鸿蒙系统中</p></blockquote><p data-v-da27ea3f><img src="'+e+'" alt="ElectronEgg demo 在鸿蒙应用中心" data-v-da27ea3f></p><blockquote data-v-da27ea3f><p data-v-da27ea3f>应用启动</p></blockquote><p data-v-da27ea3f><img src="'+t+'" alt="ElectronEgg demo 启动" data-v-da27ea3f></p><blockquote data-v-da27ea3f><p data-v-da27ea3f>框架功能演示：通信、控制器、服务等能力在鸿蒙端正常工作</p></blockquote><p data-v-da27ea3f><img src="'+d+'" alt="ElectronEgg demo 功能演示" data-v-da27ea3f></p><blockquote data-v-da27ea3f><p data-v-da27ea3f>加载本地图片功能演示</p></blockquote><p data-v-da27ea3f><img src="'+o+'" alt="ElectronEgg demo 功能演示" data-v-da27ea3f></p><blockquote data-v-da27ea3f><p data-v-da27ea3f>dock 栏功能演示</p></blockquote><p data-v-da27ea3f><img src="'+r+'" alt="ElectronEgg demo 功能演示" data-v-da27ea3f></p><blockquote data-v-da27ea3f><p data-v-da27ea3f>加载web页面功能演示</p></blockquote><p data-v-da27ea3f><img src="'+l+'" alt="ElectronEgg demo 功能演示" data-v-da27ea3f></p><p data-v-da27ea3f>可以看到，原本在 Windows / Mac 上运行的桌面应用，在鸿蒙端从安装到各项功能都跑得很顺畅。这就是 v5 鸿蒙支持想表达的核心：<strong data-v-da27ea3f>跨端不再是口号，鸿蒙是一等公民。</strong></p><h2 id="v5-还升级了什么" tabindex="-1" data-v-da27ea3f>v5 还升级了什么 <a class="header-anchor" href="#v5-还升级了什么" aria-label="Permalink to &quot;v5 还升级了什么&quot;" data-v-da27ea3f>​</a></h2><p data-v-da27ea3f>除了鸿蒙支持，v5 对框架内核做了一次较为彻底的重构：</p><ul data-v-da27ea3f><li data-v-da27ea3f>TypeScript 全面重构：所有 API 均有完整类型定义。</li><li data-v-da27ea3f>双模块格式输出：同时支持 CJS 和 ESM 两种格式。</li><li data-v-da27ea3f>Pino 日志体系：更强大的日志记录功能。</li><li data-v-da27ea3f>Bundle 注册表机制：启动更快。</li><li data-v-da27ea3f>主进程打包： 主进程代码可以像前端 bundle 。</li><li data-v-da27ea3f>构建配置全面增强：新增大量精细控制项。</li><li data-v-da27ea3f>加密系统升级： 更安全。</li><li data-v-da27ea3f>ee-bin 全面升级：新增完整 TypeScript 类型体系。</li></ul><h2 id="谁适合用" tabindex="-1" data-v-da27ea3f>谁适合用 <a class="header-anchor" href="#谁适合用" aria-label="Permalink to &quot;谁适合用&quot;" data-v-da27ea3f>​</a></h2><ul data-v-da27ea3f><li data-v-da27ea3f>想用前端技术栈（Vue / React / HTML）做桌面软件的开发者</li><li data-v-da27ea3f>需要把内部工具、管理后台、办公软件交付为桌面应用团队</li><li data-v-da27ea3f>要同时覆盖 Windows、Mac、Linux，<strong data-v-da27ea3f>以及鸿蒙</strong>的产品</li><li data-v-da27ea3f>希望降低 Electron 上手成本、想要一套清晰架构的团队</li></ul><p data-v-da27ea3f>无论你是前端、服务端、运维还是客户端开发者，都能很快入门。</p><h2 id="写在最后" tabindex="-1" data-v-da27ea3f>写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;" data-v-da27ea3f>​</a></h2><p data-v-da27ea3f>桌面软件（办公方向、个人工具）仍然是未来十几年 PC 端的刚需之一。ElectronEgg 想做的，是让这件事变得简单——而现在，这份&quot;简单&quot;也延伸到了鸿蒙。</p><p data-v-da27ea3f>框架已广泛应用于记账、政务、企业、医疗、学校、股票交易、ERP、娱乐、视频等领域的客户端，欢迎放心使用。</p><div class="tip custom-block" data-v-da27ea3f><p class="custom-block-title" data-v-da27ea3f>开源与社区</p><ul data-v-da27ea3f><li data-v-da27ea3f>GitHub：<a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-da27ea3f>https://github.com/dromara/electron-egg</a></li><li data-v-da27ea3f>Gitee：<a href="https://gitee.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-da27ea3f>https://gitee.com/dromara/electron-egg</a></li></ul></div><p data-v-da27ea3f>如果对你有帮助，欢迎 Star 支持，也欢迎加入社区一起交流。</p>',33)])])}const k=n(i,[["render",c],["__scopeId","data-v-da27ea3f"]]);export{E as __pageData,k as default};
